<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('users') ?></h1><div class="grid"><section class="card"><div class="toolbar"><h2><?= $editing?View::t('edit_user'):View::t('new_user') ?></h2><?php if($editing): ?><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/admin/users"><?= View::t('cancel') ?></a><?php endif; ?></div><form method="post" action="<?= View::e($basePath) ?><?= $editing?'/admin/users/'.View::e($editing['id']):'/admin/users' ?>"><?= View::csrf() ?><label><?= View::t('username') ?><input name="username" required value="<?= View::e($editing['username']??'') ?>"></label><label><?= View::t('display_name') ?><input name="display_name" value="<?= View::e($editing['display_name']??'') ?>"></label><label><?= View::t('email') ?><input name="email" type="email" value="<?= View::e($editing['email']??'') ?>"></label><label><?= View::t('password') ?><input name="password" type="password" minlength="12" <?= $editing?'':'required' ?> autocomplete="new-password"><?php if($editing): ?><small><?= View::t('password_unchanged') ?></small><?php endif; ?></label><label><?= View::t('role') ?><select name="role" <?= $editing&&$editing['id']===$app->auth()->user()['id']?'disabled':'' ?>><?php foreach(['viewer','operator','manager','admin'] as $role): ?><option value="<?= $role ?>" <?= ($editing['role']??'viewer')===$role?'selected':'' ?>><?= View::t('role_'.$role) ?></option><?php endforeach; ?></select><?php if($editing&&$editing['id']===$app->auth()->user()['id']): ?><input type="hidden" name="role" value="admin"><?php endif; ?></label><label><?= View::t('language') ?><select name="locale"><option value="cs" <?= ($editing['locale']??'cs')==='cs'?'selected':'' ?>>Čeština</option><option value="en" <?= ($editing['locale']??'cs')==='en'?'selected':'' ?>>English</option></select></label><button class="action-button"><?= View::t('save') ?></button></form></section><section><div class="table-wrap"><table><thead><tr><th><?= View::t('username') ?></th><th><?= View::t('role') ?></th><th><?= View::t('status') ?></th><th><?= View::t('last_login') ?></th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= View::e($u['display_name']) ?></strong><br><small><?= View::e($u['username']) ?></small></td><td><?= View::t('role_'.$u['role']) ?></td><td><?= $u['is_active']?View::t('active'):View::t('disabled') ?></td><td><?= View::e($u['last_login_at']??'—') ?></td><td><div class="actions"><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/admin/users/<?= View::e($u['id']) ?>/edit"><?= View::t('edit') ?></a><?php if($u['id']!==$app->auth()->user()['id']): ?><form method="post" action="<?= View::e($basePath) ?>/admin/users/<?= View::e($u['id']) ?>/toggle"><?= View::csrf() ?><button class="secondary-button action-button"><?= $u['is_active']?View::t('disable'):View::t('enable') ?></button></form><form method="post" action="<?= View::e($basePath) ?>/admin/users/<?= View::e($u['id']) ?>/delete"><?= View::csrf() ?><button class="danger-button action-button"><?= View::t('delete') ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></section></div>
